// Built-in Dutch rhyme word library.
// Each entry is [word, difficulty, ipa], where difficulty is one of:
//   "easy" | "intermediate" | "complex"
// IPA transcriptions sourced from the Instituut voor de Nederlandse Taal (INT)
// dataset distributed via https://github.com/open-dict-data/ipa-dict (CC BY).
// Expanded beyond the original curated 4,000 (filtered against the OpenTaal
// basiswoorden dictionary to keep out junk/non-standard entries) to fill out
// sparse rhyme families — grouped by stressed vowel + everything after it —
// so pairing doesn't keep reusing the same couple of words for a sound.
// Difficulty tiers were computed (scripts/rebuild-difficulty-tiers.py) from
// wordfreq Zipf frequency + syllable count — see the same script's docstring
// (and the comment in data/words-data.js) for the method and its known
// limitations; the rhyme-family expansion above had made "easy" especially
// bloated (77% of the list) since words were added there without checking
// difficulty, so this tier is much smaller and stricter now.
